import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

l1_normalize_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void l1_normalize_kernel(const float* x, float* out, int dim) {
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int elements_per_thread = (dim + blockDim.x - 1) / blockDim.x;
    int start = tid * elements_per_thread;
    int end = min(start + elements_per_thread, dim);

    float sum = 0.0f;
    for (int k = start; k < end; ++k) {
        sum += fabsf(x[row * dim + k]);
    }

    __shared__ float sdata[256];
    sdata[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float row_sum = sdata[0] + 1e-8f;

    for (int k = start; k < end; ++k) {
        out[row * dim + k] = x[row * dim + k] / row_sum;
    }
}

torch::Tensor l1_normalize_cuda(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    auto out = torch::empty_like(x);
    int batch_size = x.size(0);
    int dim = x.size(1);

    const int block_size = 256;
    l1_normalize_kernel<<<batch_size, block_size>>>(
        x.data_ptr<float>(), 
        out.data_ptr<float>(), 
        dim
    );

    return out;
}
"""

l1_normalize_cpp_source = "torch::Tensor l1_normalize_cuda(torch::Tensor x);"

l1_normalize = load_inline(
    name='l1_normalize',
    cpp_sources=l1_normalize_cpp_source,
    cuda_sources=l1_normalize_source,
    functions=['l1_normalize_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.l1_normalize = l1_normalize.l1_normalize_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.l1_normalize(x)
